"""AutoSuspend: a program that asked for it stops while its window is not in front, and goes on when it is.

  autosuspend.py BLITZCC on|off WORKDIR

Needs an X server (run it under xvfb-run) and xdotool, which moves the focus away from the window and back. Without
them it is skipped (exit code 77).
"""
import os
import shutil
import subprocess
import sys
import time
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "../../tools"))
import procutil  # noqa: E402

SKIP = 77


def frames(path):
    # The program replaces the file with CopyFile, which is not atomic: a read in the middle of it sees an empty file.
    # That is retried, or a frame count of 0 would be mistaken for a program that stands still.
    for _ in range(20):
        try:
            with open(path) as f:
                return int(f.read().strip())
        except (OSError, ValueError):
            time.sleep(0.01)
    return 0


def wait_for(condition, seconds):
    end = time.time() + seconds
    while time.time() < end:
        if condition():
            return True
        time.sleep(0.05)
    return False


def main():
    blitzcc, mode, work = sys.argv[1], sys.argv[2], os.path.abspath(sys.argv[3])
    if not os.environ.get("DISPLAY") or not shutil.which("xdotool") or not shutil.which("xwininfo"):
        print("autosuspend: there is no X server or no xdotool, so this is skipped.")
        return SKIP
    os.makedirs(work, exist_ok=True)
    source = os.path.join(os.path.dirname(os.path.abspath(__file__)), "autosuspend.bb")
    exe = os.path.join(work, "autosuspend")
    # BLITZCC_OPTIONS (for example "-d") adds options to the compiler, so that the test runs in Debug as well.
    procutil.run([blitzcc] + os.environ.get("BLITZCC_OPTIONS", "").split() + [source, "-o", exe], check=True, stdout=subprocess.DEVNULL)
    progress = os.path.join(work, "progress.txt")
    if os.path.exists(progress):
        os.remove(progress)
    env = dict(os.environ, BLITZLLVM_TEST_PROGRESS=progress, BLITZLLVM_TEST_SECONDS="20", BLITZLLVM_TEST_SUSPEND="1" if mode == "on" else "0")
    program = procutil.Popen([exe], env=env, cwd=work)
    try:
        window = None

        def found():
            nonlocal window
            out = procutil.run(["xdotool", "search", "--pid", str(program.pid)], capture_output=True, text=True).stdout.split()
            window = out[0] if out else None
            return window is not None

        assert wait_for(found, 20), "the window of the program was not found"
        procutil.run(["xdotool", "windowfocus", window], check=True)
        assert wait_for(lambda: frames(progress) > 0, 20), "the program did not start drawing"

        root = None
        for line in procutil.run(["xwininfo", "-root"], capture_output=True, text=True).stdout.splitlines():
            if "Window id" in line:
                root = line.split()[3]
        assert root, "the root window was not found"

        # The window loses the focus: a program that is suspended stands still, the others do not.
        procutil.run(["xdotool", "windowfocus", root], check=True)
        time.sleep(0.5)
        before = frames(progress)
        time.sleep(1.0)
        after = frames(progress)
        if mode == "on":
            assert after == before, f"the program ran while suspended: {before} -> {after} frames"
        else:
            assert after > before, f"the program stopped without AutoSuspend: {before} -> {after} frames"

        # And goes on when it is in front again.
        procutil.run(["xdotool", "windowfocus", window], check=True)
        assert wait_for(lambda: frames(progress) > after, 5), "the program did not go on when its window was in front"
    finally:
        program.kill()
        program.wait()
    print(f"autosuspend {mode}: ok")
    return 0


if __name__ == "__main__":
    sys.exit(main())
